hot-air-balloon.source:
const h = params.height;
const hover = 1;
const basketH = h * 0.14;
const basketW = h * 0.13;
const basketD = h * 0.105;
const gap = h * 0.055;
const envBottom = hover + basketH + gap;
const envH = h - basketH - gap;
const R = h * 0.245;
const segs = 24;
const profile = [];
const rings = 18;
for (let i = 0; i <= rings; i++) {
  const t = i / rings;
  const y = envBottom + t * envH;
  let r = R * Math.pow(Math.sin(Math.PI * t), 0.62) * (0.48 + 0.72 * t);
  if (i === 0 || i === rings) r = 0;
  profile.push([r, y]);
}
const envelope = api.lathe(profile, segs);
envelope.vertexColor((x, y, z) => {
  let a = Math.atan2(z, x);
  if (a < 0) a += Math.PI * 2;
  const panel = Math.floor((a / (Math.PI * 2)) * 12);
  const base = panel % 2 === 0 ? params.color : params.stripeColor;
  const vertical = (y - envBottom) / envH;
  const shade = 0.05 + 0.12 * Math.abs(vertical - 0.55);
  return api.mix(base, '#5a2630', shade);
});
api.add(envelope, { preset: 'fabric', roughness: 0.86, flatShading: true });
const dark = { preset: 'metal', color: '#393638', metalness: 0.65, roughness: 0.38 };
const ropeMat = { preset: 'fabric', color: '#6b4529', roughness: 1 };
const wicker = { preset: 'wood', color: '#a66a32', roughness: 0.9 };
const wickerDark = { preset: 'wood', color: '#68401f', roughness: 0.95 };
const burnerMat = { preset: 'metal', color: '#9b8d78', metalness: 0.75, roughness: 0.28 };
const basketY = hover + basketH * 0.5;
const wall = basketW * 0.08;
api.add(api.box(basketW, wall, basketD).translate(0, hover + wall * 0.5, 0), wickerDark);
api.add(api.box(basketW, basketH, wall).translate(0, basketY, basketD * 0.5 - wall * 0.5), wicker);
api.add(api.box(basketW, basketH, wall).translate(0, basketY, -basketD * 0.5 + wall * 0.5), wicker);
api.add(api.box(wall, basketH, basketD - wall * 2).translate(-basketW * 0.5 + wall * 0.5, basketY, 0), wicker);
api.add(api.box(wall, basketH, basketD - wall * 2).translate(basketW * 0.5 - wall * 0.5, basketY, 0), wicker);
for (let i = 0; i < 4; i++) {
  const yy = hover + basketH * (0.2 + i * 0.21);
  api.add(api.box(basketW * 1.035, wall * 0.32, basketD * 1.035).translate(0, yy, 0), wickerDark);
}
for (let i = -2; i <= 2; i++) {
  const x = i * basketW * 0.19;
  api.add(api.box(wall * 0.28, basketH * 0.92, wall * 0.45).translate(x, basketY, basketD * 0.515), wickerDark);
  api.add(api.box(wall * 0.28, basketH * 0.92, wall * 0.45).translate(x, basketY, -basketD * 0.515), wickerDark);
}
for (let i = -1; i <= 1; i++) {
  const z = i * basketD * 0.25;
  api.add(api.box(wall * 0.45, basketH * 0.92, wall * 0.28).translate(basketW * 0.515, basketY, z), wickerDark);
  api.add(api.box(wall * 0.45, basketH * 0.92, wall * 0.28).translate(-basketW * 0.515, basketY, z), wickerDark);
}
const frameY = hover + basketH + gap * 0.35;
api.add(api.box(basketW * 0.82, wall * 0.5, wall * 0.5).translate(0, frameY, 0), dark);
api.add(api.box(wall * 0.5, wall * 0.5, basketD * 0.72).translate(0, frameY, 0), dark);
const burnerY = hover + basketH + gap * 0.28;
for (let s = -1; s <= 1; s += 2) {
  api.add(api.cylinder(basketW * 0.095, basketW * 0.12, gap * 0.46, 10).translate(s * basketW * 0.18, burnerY, 0), burnerMat);
  api.add(api.cone(basketW * 0.055, gap * 0.38, 8).translate(s * basketW * 0.18, burnerY + gap * 0.35, 0), { preset: 'emissive', color: '#ff9b32', emissive: '#ff6a19', emissiveIntensity: 2.6, opacity: 0.9 });
}
const ropeR = h * 0.006;
const bx = basketW * 0.47;
const bz = basketD * 0.47;
const attachY = envBottom + envH * 0.18;
const attachR = R * 0.67;
const corners = [[-bx,-bz],[bx,-bz],[bx,bz],[-bx,bz]];
for (let i = 0; i < 4; i++) {
  const sx = corners[i][0];
  const sz = corners[i][1];
  const len = Math.sqrt(sx * sx + sz * sz);
  const ex = sx / len * attachR;
  const ez = sz / len * attachR;
  api.add(api.tube([[sx, hover + basketH * 0.88, sz],[sx * 1.25, envBottom - gap * 0.08, sz * 1.25],[ex, attachY, ez]], ropeR, 5), ropeMat);
}
api.add(api.torus(R * 0.19, ropeR * 1.4).rotate(90, 0, 0).translate(0, envBottom + envH * 0.055, 0), ropeMat);
api.add(api.cylinder(R * 0.14, R * 0.17, h * 0.025, 12).translate(0, envBottom + h * 0.012, 0), dark);
api.add(api.cylinder(h * 0.16, h * 0.16, h * 0.006, 24).translate(0, h * 0.003, 0), { preset: 'concrete', color: '#544f4a', roughness: 1, opacity: 0.28 });
api.collider({ kind: 'box', halfExtents: [basketW * 0.5, basketH * 0.5, basketD * 0.5], offset: [0, basketY, 0] });
api.collider({ kind: 'sphere', radius: R * 0.82, offset: [0, envBottom + envH * 0.55, 0] });
return api.build();

saguaro-cactus.source:
const h = params.height;
const armCount = params.arms;
const r = h * 0.085;
const cactusMat = { preset: 'leaf', color: params.color, roughness: 0.82, flatShading: true };
const ribMat = { preset: 'leaf', color: api.mix(params.color, '#d4dfa0', 0.15), roughness: 0.88, flatShading: true };
const flowerMat = { preset: 'leaf', color: '#f4c9c5', roughness: 0.68, flatShading: true };
const flowerCenterMat = { preset: 'leaf', color: '#e6b84f', roughness: 0.72, flatShading: true };

const trunkProfile = [
  [r * 0.82, 0],
  [r, h * 0.055],
  [r * 1.02, h * 0.48],
  [r * 0.96, h * 0.82],
  [r * 0.76, h * 0.97],
  [r * 0.42, h]
];
api.add(api.lathe(trunkProfile, 16), cactusMat);

const ribCount = 12;
for (let i = 0; i < ribCount; i++) {
  const a = i * Math.PI * 2 / ribCount;
  const ca = Math.cos(a);
  const sa = Math.sin(a);
  const path = [
    [ca * r * 0.91, h * 0.045, sa * r * 0.91],
    [ca * r * 1.035, h * 0.18, sa * r * 1.035],
    [ca * r * 1.045, h * 0.5, sa * r * 1.045],
    [ca * r * 0.97, h * 0.82, sa * r * 0.97],
    [ca * r * 0.68, h * 0.975, sa * r * 0.68]
  ];
  api.add(api.tube(path, r * 0.075, 5), ribMat);
}

function addFlower(x, y, z, scale) {
  const petals = 7;
  for (let p = 0; p < petals; p++) {
    const a = p * Math.PI * 2 / petals;
    api.add(api.sphere(scale * 0.19, 1).scale(1.55, 0.42, 0.82).rotate(0, -p * 360 / petals, 0).translate(x + Math.cos(a) * scale * 0.2, y, z + Math.sin(a) * scale * 0.2), flowerMat);
  }
  api.add(api.sphere(scale * 0.13, 1).scale(1, 0.65, 1).translate(x, y + scale * 0.025, z), flowerCenterMat);
}

addFlower(0, h + r * 0.08, 0, r * 0.8);

for (let i = 0; i < armCount; i++) {
  const angle = (i / Math.max(1, armCount)) * Math.PI * 2 + 0.38 + (api.rng() - 0.5) * 0.18;
  const ca = Math.cos(angle);
  const sa = Math.sin(angle);
  const sideX = -sa;
  const sideZ = ca;
  const joinY = h * (0.34 + i * 0.095 + (api.rng() - 0.5) * 0.035);
  const reach = h * (0.16 + 0.018 * (i % 2));
  const rise = h * (0.23 + 0.025 * ((i + 1) % 3));
  const ar = r * 0.57;
  const elbowX = ca * reach;
  const elbowZ = sa * reach;
  const tipY = joinY + rise;
  const armPath = [
    [ca * r * 0.55, joinY - ar * 0.15, sa * r * 0.55],
    [ca * r * 1.15, joinY, sa * r * 1.15],
    [ca * reach * 0.72, joinY + ar * 0.08, sa * reach * 0.72],
    [elbowX, joinY + ar * 0.55, elbowZ],
    [elbowX, tipY - ar * 0.55, elbowZ],
    [elbowX, tipY, elbowZ]
  ];
  api.add(api.tube(armPath, ar, 10), cactusMat);

  for (let q = 0; q < 6; q++) {
    const b = q * Math.PI * 2 / 6;
    const ox = sideX * Math.cos(b) * ar * 0.93 + ca * Math.sin(b) * ar * 0.93;
    const oz = sideZ * Math.cos(b) * ar * 0.93 + sa * Math.sin(b) * ar * 0.93;
    const ridgePath = [
      [ca * reach * 0.76 + sideX * Math.cos(b) * ar * 0.75, joinY + ar * 0.15 + Math.sin(b) * ar * 0.3, sa * reach * 0.76 + sideZ * Math.cos(b) * ar * 0.75],
      [elbowX + ox, joinY + ar * 0.62, elbowZ + oz],
      [elbowX + ox, tipY - ar * 0.22, elbowZ + oz]
    ];
    api.add(api.tube(ridgePath, ar * 0.075, 4), ribMat);
  }

  addFlower(elbowX, tipY + ar * 0.62, elbowZ, ar * 0.9);
  api.collider({ kind: 'box', halfExtents: [reach * 0.48, ar, ar], offset: [ca * reach * 0.52, joinY + ar * 0.2, sa * reach * 0.52], rotation: [0, -angle * 180 / Math.PI, 0] });
  api.collider({ kind: 'capsule', halfHeight: rise * 0.48, radius: ar, offset: [elbowX, joinY + rise * 0.52, elbowZ] });
}

api.collider({ kind: 'capsule', halfHeight: h * 0.47, radius: r, offset: [0, h * 0.49, 0] });
return api.build();
